from __future__ import annotations
import csv,json,hashlib,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from astra.core import Bar,backtest,adversary
from astra.research import Experiment,walk_forward,cost_stress
DATA=ROOT/"data/real/kraken_BTCUSD_1d.csv"; OUT=ROOT/"evidence/real_data_research_ci.json"
def sha256(p):
 h=hashlib.sha256()
 with p.open("rb") as f:
  for c in iter(lambda:f.read(1024*1024),b""): h.update(c)
 return h.hexdigest()
def main():
 with DATA.open(encoding="utf-8") as f: rows=list(csv.DictReader(f))
 bars=[Bar(i,float(r["close"])) for i,r in enumerate(rows)]
 base=backtest(bars); adv=adversary(bars); wf=walk_forward(bars,Experiment(12,40,300,100,100)); costs=cost_stress(bars,12,40)
 ev={"status":"PROVEN_RESEARCH_RUN","dataset_sha256":sha256(DATA),"rows":len(bars),"source":"Kraken public REST API","dataset_synthetic":False,"baseline":base,"adversary":adv,"walk_forward":{"folds":wf.folds,"test_returns":wf.test_returns,"mean_return_pct":wf.mean_return_pct,"positive_fold_ratio":wf.positive_fold_ratio,"max_drawdown_pct":wf.max_drawdown_pct,"aggregate_return_pct":wf.aggregate_return_pct,"passed_gate":wf.passed},"cost_stress":costs,"profitability":"UNVERIFIED","live_money_execution":False}
 OUT.write_text(json.dumps(ev,indent=2,sort_keys=True)+"\n",encoding="utf-8"); print(json.dumps(ev,indent=2))
if __name__=="__main__": main()

from __future__ import annotations
import csv,json,hashlib,sys
from pathlib import Path
from statistics import mean
ROOT=Path(__file__).resolve().parents[1]; sys.path.insert(0,str(ROOT))
from astra.core import Bar,backtest_signals
from astra.strategies import trend,mean_reversion,breakout,long_momentum,long_trend
FEE=0.0005; SLIP=0.0002; TRAIN=300; TEST=100; STEP=100; EMBARGO=5
ASSETS=("BTCUSD","ETHUSD","SOLUSD","LTCUSD")
CANDIDATES=[]
for f in (4,6,8,10,12,16,20):
 for s in (24,32,40,52,64,80):
  if f<s: CANDIDATES.append(("trend",{"fast":f,"slow":s},trend,s))
for w in (10,15,20,30,40,60):
 for z in (0.5,1.0,1.5,2.0,3.0): CANDIDATES.append(("mean_reversion",{"window":w,"z":z},mean_reversion,w))
for w in (10,15,20,30,40,60,80): CANDIDATES.append(("breakout",{"window":w},breakout,w))
for w in (10,20,30,40,60,80,120):
 for threshold in (0.0,2.0,5.0,10.0): CANDIDATES.append(("long_momentum",{"window":w,"threshold":threshold},long_momentum,w))
for f in (10,20,30,40):
 for s in (50,80,120,160):
  if f<s: CANDIDATES.append(("long_trend",{"fast":f,"slow":s},long_trend,s))
def sha256(p):
 h=hashlib.sha256()
 with p.open("rb") as f:
  for c in iter(lambda:f.read(1024*1024),b""): h.update(c)
 return h.hexdigest()
def load(symbol):
 rows=list(csv.DictReader((ROOT/"data/real"/f"kraken_{symbol}_1d.csv").open(encoding="utf-8")))
 return [Bar(i,float(r["close"])) for i,r in enumerate(rows)]
def signal_for(bars,name,p):
 return {"trend":trend,"mean_reversion":mean_reversion,"breakout":breakout,"long_momentum":long_momentum,"long_trend":long_trend}[name](bars,**p)
def rank_train(data,start):
 rows=[]
 for name,p,_,_ in CANDIDATES:
  sub=[]
  for sym,bars in data.items():
   a=bars[start:start+150]; b=bars[start+150:start+TRAIN]
   ra=backtest_signals(a,signal_for(a,name,p),fee=FEE,slip=SLIP)
   rb=backtest_signals(b,signal_for(b,name,p),fee=FEE,slip=SLIP)
   agg=((1+ra["return_pct"]/100)*(1+rb["return_pct"]/100)-1)*100
   sub.append((ra["return_pct"],rb["return_pct"],max(ra["max_drawdown_pct"],rb["max_drawdown_pct"]),agg))
  total_trades=0
  for sym,bars in data.items():
   a=bars[start:start+150]; b=bars[start+150:start+TRAIN]
   total_trades += backtest_signals(a,signal_for(a,name,p),fee=FEE,slip=SLIP)["trades"] + backtest_signals(b,signal_for(b,name,p),fee=FEE,slip=SLIP)["trades"]
  if total_trades >= 8:
   rows.append((min(x for q in sub for x in q[:2]),-max(x[2] for x in sub),mean(x[3] for x in sub),name,p,total_trades))
 if not rows: raise RuntimeError("no active candidate met the training activity floor")
 return max(rows,key=lambda x:x[:3])
def run():
 data={s:load(s) for s in ASSETS}
 if min(len(v) for v in data.values())<TRAIN+EMBARGO+TEST: raise RuntimeError("insufficient aligned real data")
 folds=[]; start=0
 while start+TRAIN+EMBARGO+TEST<=min(len(v) for v in data.values()):
  selected=rank_train(data,start); name,p=selected[3],selected[4]
  asset_tests={}
  benchmarks={}
  for sym,bars in data.items():
   test_start=start+TRAIN+EMBARGO; test_end=test_start+TEST
   lookback=max([int(v) for k,v in p.items() if k in ("fast","slow","window")] or [1])
   context_start=max(0,test_start-lookback)
   context=bars[context_start:test_end]; off=test_start-context_start
   test_bars=context[off:]
   test_sigs=signal_for(context,name,p)[off:]
   asset_tests[sym]=backtest_signals(test_bars,test_sigs,fee=FEE,slip=SLIP)
   bh=(test_bars[-1].close/test_bars[0].close-1)*100 if len(test_bars)>1 else 0.0
   benchmarks[sym]=round(bh,4)
  folds.append({"fold":len(folds)+1,"train_start":start,"train_end":start+TRAIN-1,"test_start":start+TRAIN+EMBARGO,"test_end":start+TRAIN+EMBARGO+TEST-1,"selected":name,"params":p,"train_stability_score":selected[0],"train_max_dd":-selected[1],"train_mean_aggregate_return_pct":selected[2],"train_activity_trades":selected[5],"asset_tests":asset_tests,"buy_hold_return_pct":benchmarks})
  start+=STEP
 fold_returns=[mean(v["return_pct"] for v in f["asset_tests"].values()) for f in folds]
 fold_bh_returns=[mean(f["buy_hold_return_pct"].values()) for f in folds]
 all_asset_returns=[v["return_pct"] for f in folds for v in f["asset_tests"].values()]
 wealth=1.0
 for x in fold_returns: wealth*=1+x/100
 agg=(wealth-1)*100
 maxdd=max(v["max_drawdown_pct"] for f in folds for v in f["asset_tests"].values())
 bh_wealth=1.0
 for x in fold_bh_returns: bh_wealth*=1+x/100
 bh_agg=(bh_wealth-1)*100
 positive=sum(x>0 for x in all_asset_returns)/len(all_asset_returns)
 ev={"status":"PROVEN_CROSS_ASSET_RESEARCH","dataset_sha256":{s:sha256(ROOT/"data/real"/f"kraken_{s}_1d.csv") for s in ASSETS},"rows":{s:len(v) for s,v in data.items()},"candidate_count":len(CANDIDATES),"folds":folds,"summary":{"folds":len(folds),"mean_asset_fold_return_pct":round(mean(fold_returns),4),"positive_asset_fold_ratio":round(positive,4),"aggregate_equal_weight_fold_return_pct":round(agg,4),"max_asset_drawdown_pct":round(maxdd,4),"buy_hold_aggregate_return_pct":round(bh_agg,4),"strategy_vs_buy_hold_pct":round(agg-bh_agg,4),"passed_gate":agg>0 and positive>=0.5 and maxdd<=8.0},"cost":{"fee":FEE,"slip":SLIP},"profitability":"UNVERIFIED","live_money_execution":False}
 out=ROOT/"evidence/cross_asset_research_ci.json"; out.write_text(json.dumps(ev,indent=2,sort_keys=True)+"\n",encoding="utf-8"); print(json.dumps(ev,indent=2))
if __name__=="__main__": run()

from astra.core import market
from astra.research import Experiment, walk_forward
def test_walk_forward_selects_on_train_and_tests_future_window():
    r=walk_forward(market(900, seed=19), Experiment(6,40,300,100,100)); assert r.folds == 6 and len(r.test_returns) == 6
def test_walk_forward_rejects_insufficient_data():
    try: walk_forward(market(100, seed=19), Experiment(6,40,300,100,100))
    except ValueError: return
    assert False
def test_strategy_tournament_has_multiple_families():
    from astra.research import strategy_tournament
    rows = strategy_tournament(market(500, seed=23)); assert len(rows) == 4
    assert {r['name'] for r in rows} == {'trend','mean_reversion','breakout'}
    assert all('return_pct' in r and 'max_drawdown_pct' in r for r in rows)
def test_regime_detector_is_deterministic():
    from astra.strategies import regime
    a=regime(market(300,seed=4)); b=regime(market(300,seed=4)); assert a == b and set(a) <= {'unknown','trend','range'}
